const{test}=require('node:test');const assert=require('node:assert/strict');const{resolveSession}=require('./modules/dashboard/cockpit.service.js');
test('verified highest role preserves management capability across modules',()=>{const x=resolveSession({userId:'test-unlisted',userName:'Unlisted',authority:'central_authority',highestBusinessAccess:true});assert.equal(x.role,'director');assert.equal(x.permissionBasis,'central_authority');assert.equal(x.canViewCriticalWork,true);assert.equal(x.canViewDirectorBriefing,true);assert.equal(x.canEditDirectorBriefing,true);});
test('raw highest flag and ordinary central viewer do not gain management',()=>{for(const identity of [{highestBusinessAccess:true},{authority:'central_authority',highestBusinessAccess:false}]){const x=resolveSession({userId:'test-unlisted',userName:'Unlisted',...identity});assert.equal(x.role,'viewer');assert.equal(x.canEditDirectorBriefing,false);}});
